function configMessage(){return `<div class="configuration-message${configError?' error':''}" role="status">${safe(configError|| (configSaving?'Saving…':configurationMessage()))}</div>`}
function managementView(){
 if(configLoading)return heading('Manage nodes','',true)+'<div class="empty">Loading configuration…</div>';
 if(!configuration)return heading('Manage nodes','',true)+configMessage()+'<button class="config-primary" data-action="config-reload">Retry setup connection</button>';
 return heading('Manage nodes',`${configuration.nodes.length} / ${configuration.max_nodes||4}`,true)+configMessage()+configuration.nodes.map(n=>`<div class="list-row config-node"><div class="row-top"><span class="row-name">${safe(n.name)}</span><span class="tag">${safe(configType(n.type))}</span></div><div class="row-bottom config-address">${safe(n.url||configuration.local_node?.address||'Local collector')}</div><div class="config-actions"><button data-edit-node="${safe(n.id)}">Edit</button><button class="danger" data-delete-node="${safe(n.id)}">Delete</button></div></div>`).join('')+`<button class="config-primary" data-action="config-add" ${configuration.nodes.length>=(configuration.max_nodes||4)?'disabled':''}>Add monitor node</button>`;
}
function nodeFormView(){
 const d=configDraft,editing=configuration?.nodes.some(n=>n.id===d?.id);if(!d)return managementView();
 const types=[['klipper','Klipper printer'],['proxmox-feed','Remote Proxmox']];if(!configuration.nodes.some(n=>n.type==='local-proxmox'))types.unshift(['local-proxmox','Local Proxmox']);
 return heading(editing?'Edit monitor node':'Add monitor node','',true)+`<form id="node-form" method="post" data-nonce="${configDraftNonce}">${configMessage()}${editing?`<div class="reading-message">${safe(configType(d.type))} · ${safe(d.id)}</div>`:`<label class="config-field">Node type<select name="type">${types.map(([value,label])=>`<option value="${value}" ${d.type===value?'selected':''}>${label}</option>`).join('')}</select></label>`}<label class="config-field">Display name<input name="name" value="${safe(d.name||'')}" maxlength="64" required autocomplete="off"></label>${!editing&&d.type!=='local-proxmox'?`<label class="config-field">ID · optional<input name="id" value="${safe(d.id||'')}" maxlength="32" placeholder="Auto from name" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off"></label>`:''}${d.type==='local-proxmox'?`<div class="reading-message">Local collector · ${safe(configuration.local_node?.address||'')}</div>`:`<label class="config-field">${d.type==='klipper'?'Moonraker URL':'Snapshot feed URL'}<input name="url" value="${safe(d.url||'')}" type="url" maxlength="512" required placeholder="${d.type==='klipper'?'http://printer.local:7125':'http://server.local:8765/api/v1/snapshot'}" autocomplete="off"></label><label class="config-field">${d.type==='klipper'?'API key · optional':'Feed token'}<input name="secret" type="password" maxlength="256" autocomplete="new-password" placeholder="${d.has_secret?'Saved · keep for the same address':'Enter key if required'}"></label>${d.has_secret?'<label class="config-check"><input name="clear_secret" type="checkbox">Clear saved key</label>':''}<div class="config-numbers">${[['poll_interval_s','Refresh · seconds',5,2,300,1],['timeout_s','Timeout · seconds',2.5,.5,3,.5],['ttl_s','Stale after · seconds',15,5,900,1]].map(([name,label,fallback,min,max,step])=>`<label class="config-field">${label}<input name="${name}" type="number" value="${safe(d[name]??fallback)}" min="${min}" max="${max}" step="${step}" required></label>`).join('')}</div>`}<div class="config-actions"><button type="button" data-action="config-cancel">Cancel</button><button class="config-primary" type="submit" ${configSaving?'disabled':''}>Save node</button></div></form>`;
}
function deleteView(){const n=configuration?.nodes.find(n=>n.id===configDeleteId);return heading('Delete monitor node','',true)+configMessage()+`<div class="delete-question">Remove <strong>${safe(n?.name||configDeleteId)}</strong>?</div><div class="reading-message">It will disappear from the monitor.</div><div class="config-actions"><button data-action="config-cancel" ${configSaving?'disabled':''}>Cancel</button><button class="config-primary danger" data-action="config-delete-confirm" ${configSaving?'disabled':''}>Delete node</button></div>`}
function wifiView(){return heading('Device Wi-Fi','',true)+(mode==='live'?'<div class="empty">Open the gear on the ESP32 to change its Wi-Fi connection.</div>':`<form id="wifi-demo-form" method="post"><div class="configuration-message">DEMO · device setup simulation only.</div><label class="config-field">Wi-Fi name<input name="ssid" maxlength="32" required value="${safe(demoWifiSSID)}" autocomplete="off"></label><label class="config-field">Password<input name="password" type="password" maxlength="63" autocomplete="new-password"></label><button class="config-primary" type="submit">Save demo Wi-Fi</button><div id="wifi-demo-message" class="reading-message" role="status"></div></form>`)}
async function openConfiguration(){
 configEpoch++;const epoch=configEpoch;configError='';configDraft=null;configDeleteId=null;detail={kind:'node-config',back:{kind:'settings'}};configLoading=true;configApplying=false;render();
 try{if(mode==='demo')configuration=structuredClone(demoConfiguration);else{const response=await fetch('/api/v1/config',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error(response.status===401?'Setup connection is not configured on the preview server.':`Setup unavailable (HTTP ${response.status}).`);const next=await response.json();if(next.schema!==1||!Array.isArray(next.nodes)||next.version==null)throw Error('Unexpected configuration format');if(epoch!==configEpoch)return;configuration=next;}}
 catch(e){if(epoch===configEpoch){configuration=null;configError=e.message}}
 finally{if(epoch===configEpoch){configLoading=false;render()}}
}
function editConfigNode(id){const node=configuration?.nodes.find(n=>n.id===id);configError='';configDraft=node?structuredClone(node):{id:'',type:configuration?.nodes.some(n=>n.type==='local-proxmox')?'klipper':'local-proxmox',name:'',url:'',poll_interval_s:10,timeout_s:2.5,ttl_s:30,has_secret:false};configDraftNonce++;detail={kind:'node-form',back:{kind:'node-config',back:{kind:'settings'}}};$('#content').scrollTop=0;render()}
function configuredRegistry(){return configuration.nodes.map(n=>({id:n.id,type:n.type==='klipper'?'klipper':'proxmox',name:n.name,address:n.url||configuration.local_node?.address||'',status:nodes.find(old=>old.id===n.id)?.status||'unknown'}))}
function applyConfiguration(next){
 configuration=next;nodes=configuredRegistry();noNodes=!nodes.length;configDraft=null;configDeleteId=null;configError='';detail={kind:'node-config',back:{kind:'settings'}};
 if(noNodes){feedEpoch++;feedController?.abort();feedController=null;selectedNodeId='';data=emptySnapshot(null);selectionLoading=false;}
 else if(!nodes.some(n=>n.id===selectedNodeId)){selectNode(nodes[0].id);detail={kind:'node-config',back:{kind:'settings'}};}
 else if(mode==='demo')data=demoSnapshot(selectedNodeId);
 render();
}
async function mutateConfiguration(payload){
 if(configSaving)return;const epoch=configEpoch,requestMode=mode;configSaving=true;configError='';render();
 try{
  let next;
  if(mode==='demo'){
   next=structuredClone(configuration);if(payload.action==='delete')next.nodes=next.nodes.filter(n=>n.id!==payload.id);
   else{const n={...payload.node},prefix=n.type==='klipper'?'klipper:':n.type==='local-proxmox'?'proxmox:':'proxmox-feed:';if(!n.id){const slug=n.name.toLowerCase().replace(/[^a-z0-9_.-]+/g,'-').replace(/^-|-$/g,'').slice(0,28)||'node';n.id=prefix+slug;let suffix=2;while(next.nodes.some(x=>x.id===n.id))n.id=prefix+slug+'-'+suffix++;}else if(!n.id.includes(':'))n.id=prefix+n.id;
    const old=next.nodes.find(x=>x.id===n.id);n.has_secret=n.clear_secret?false:Boolean(n.secret||old?.has_secret);delete n.secret;delete n.clear_secret;next.nodes=next.nodes.filter(x=>x.id!==n.id);next.nodes.push(n);}
   next.version++;next.local_node.enabled=next.nodes.some(n=>n.type==='local-proxmox');const local=next.nodes.find(n=>n.type==='local-proxmox');if(local)next.local_node.name=local.name;demoConfiguration=structuredClone(next);
  }else{
   const body=JSON.stringify({...payload,version:configuration.version});if(new TextEncoder().encode(body).length>4096)throw Error('Configuration too large. Shorten the URL or key.');
   const response=await fetch('/api/v1/config',{method:'POST',headers:{'Content-Type':'application/json','X-Homelab-Config':'1'},body,signal:AbortSignal.timeout(8000)});
   if(epoch!==configEpoch||requestMode!==mode)return;
   if(response.status===409){configSaving=false;await openConfiguration();configError='Configuration changed. Review current nodes and retry.';render();return}
   if(!response.ok){let message=response.status===401?'Setup connection is not configured on the preview server.':`Setup unavailable (HTTP ${response.status}).`;if(response.status===400){const error=await response.json().catch(()=>({}));message=typeof error.error==='string'?error.error.slice(0,256):'Check the node settings and try again.'}throw Error(message)}
   const result=await response.json();if(!result.config||!Array.isArray(result.config.nodes))throw Error('Unexpected configuration response');next=result.config;configApplying=Boolean(result.applying);
  }
  applyConfiguration(next);
  if(configApplying)setTimeout(()=>refreshAppliedConfiguration(epoch),1500);
 }catch(e){if(epoch===configEpoch&&requestMode===mode)configError=e.message}
 finally{if(payload.node)delete payload.node.secret;if(epoch===configEpoch&&requestMode===mode){configSaving=false;render()}}
}
function registryMatchesConfiguration(registry){return configuration&&registry.length===configuration.nodes.length&&registry.every(n=>configuration.nodes.some(c=>c.id===n.id&&c.name===n.name))}
async function refreshAppliedConfiguration(epoch,attempt=0){
 if(epoch!==configEpoch||mode!=='live'||!configApplying)return;
 try{const response=await fetch('/api/v1/nodes',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(response.ok){const registry=registryEntries((await response.json()).nodes);if(epoch===configEpoch&&registryMatchesConfiguration(registry)){nodes=registry;noNodes=!registry.length;configApplying=false;render();return}}}catch{}
 if(attempt<5)setTimeout(()=>refreshAppliedConfiguration(epoch,attempt+1),2000);
}
function submitConfig(form){
 const d=configDraft,values=new FormData(form),node={id:d.id||String(values.get('id')||''),type:d.type,name:String(values.get('name')||'').trim()};
 if(node.type==='local-proxmox'&&!node.id)node.id=configuration.local_node?.id||'';
 if(node.type!=='local-proxmox'){node.url=String(values.get('url')||'').trim();for(const key of ['poll_interval_s','timeout_s','ttl_s'])node[key]=Number(values.get(key));const secret=String(values.get('secret')||'');if(secret)node.secret=secret;if(values.get('clear_secret'))node.clear_secret=true;form.elements.secret.value='';if(node.secret&&node.clear_secret){configError='Choose either a new key or clear saved key.';render();return}if(node.ttl_s<2*node.poll_interval_s){configError='Stale after must allow at least two refresh intervals.';render();return}if(secret&&(/[^\x21-\x7e]/.test(secret)||secret.length>256)){configError='Keys must use at most 256 ASCII characters without spaces.';render();return}if(node.type==='proxmox-feed'&&secret&&secret.length<32){configError='Feed tokens must contain at least 32 characters.';render();return}}
 mutateConfiguration({action:'upsert',node});
}
let history=Array.from({length:35},(_,i)=>14+Math.sin(i*.75)*4+Math.cos(i*.28)*3),ramHistory=Array.from({length:35},(_,i)=>85+Math.sin(i*.3));
function spark(arr,color,id){
 const groups=[];let group=[];
 arr.forEach((v,i)=>{if(v==null||!Number.isFinite(v)){if(group.length>1)groups.push(group);group=[];return}group.push([i/(arr.length-1)*300,35-Math.max(0,Math.min(100,v))*.3])});
 if(group.length>1)groups.push(group);if(!groups.length)return '';
 const shapes=groups.map(points=>{const p=points.map(([x,y],i)=>`${i?'L':'M'} ${x} ${y}`).join(' ');return `<path d="${p} L${points.at(-1)[0]} 36 L${points[0][0]} 36Z" fill="url(#${id})"/><path d="${p}" fill="none" stroke="currentColor" stroke-width="1.8"/>`}).join('');
 return `<svg class="spark" style="color:${color}" viewBox="0 0 300 36" preserveAspectRatio="none"><defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="currentColor" stop-opacity=".18"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>${shapes}</svg>`
}
function cell(label,value){return `<div class="detail-cell"><span>${safe(label)}</span><strong>${safe(value)}</strong></div>`}
function heading(title,right='',back=false){return `<div class="page-heading">${back?'<button class="back" data-action="back" aria-label="Back">‹</button>':''}<span>${safe(title)}</span><span class="right">${safe(right)}</span></div>`}
function bar(value,color='var(--cyan)'){return `<div class="bar"><span style="width:${value??0}%;background:${color}"></span></div>`}
